def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = 0
    my_defects = 0
    for me, opp in history:
        if opp == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    last_my, last_opp = history[-1]

    if opp_defects == 0:
        return 'C'

    if my_defects > opp_defects + 2:
        return 'C'

    opp_defect_rate = opp_defects / n

    if opp_defect_rate > 0.6:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if opp_defect_rate > 0.3:
        if last_opp == 'D':
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            return 'C'

    if last_opp == 'D':
        if rng.random() < 0.5:
            return 'C'
        return 'D'
    else:
        return 'C'
